CREATE TABLE archive_meta (id INTEGER PRIMARY KEY CHECK(id=1), epoch TEXT NOT NULL, visibility_epoch INTEGER NOT NULL DEFAULT 1, revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE publishers (publisher_id TEXT PRIMARY KEY, experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, generation TEXT NOT NULL, scope_json TEXT NOT NULL CHECK(json_valid(scope_json)), UNIQUE(experiment_id,run_id));
CREATE TABLE publisher_keys (key_id TEXT PRIMARY KEY, publisher_id TEXT NOT NULL REFERENCES publishers(publisher_id), public_key TEXT NOT NULL, not_before INTEGER NOT NULL, not_after INTEGER NOT NULL, revoked INTEGER NOT NULL CHECK(revoked IN(0,1)), CHECK(not_after>not_before));
CREATE TABLE authority_audit (id INTEGER PRIMARY KEY, recorded_at TEXT NOT NULL, publisher_id TEXT NOT NULL, action TEXT NOT NULL);
CREATE TABLE nonces (key_id TEXT NOT NULL REFERENCES publisher_keys(key_id), nonce TEXT NOT NULL, expires INTEGER NOT NULL, PRIMARY KEY(key_id,nonce));
CREATE INDEX nonce_expiry ON nonces(expires);
CREATE TABLE quotas (publisher_id TEXT NOT NULL REFERENCES publishers(publisher_id), period TEXT NOT NULL, count INTEGER NOT NULL, bytes INTEGER NOT NULL, PRIMARY KEY(publisher_id,period));
CREATE TABLE experiments (experiment_id TEXT PRIMARY KEY, created_at TEXT NOT NULL, official_run_id TEXT);
CREATE TABLE runs (experiment_id TEXT NOT NULL REFERENCES experiments(experiment_id), run_id TEXT NOT NULL, config_hash TEXT NOT NULL, published_json TEXT NOT NULL CHECK(json_valid(published_json)), evidence_mode TEXT NOT NULL, bytes INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(experiment_id,run_id));
CREATE TABLE batches (publisher_id TEXT NOT NULL REFERENCES publishers(publisher_id), experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, batch_id TEXT NOT NULL, body_digest TEXT NOT NULL, receipt_json TEXT NOT NULL CHECK(json_valid(receipt_json)), PRIMARY KEY(publisher_id,experiment_id,run_id,batch_id), FOREIGN KEY(experiment_id,run_id) REFERENCES runs(experiment_id,run_id));
CREATE TABLE events (receiver_sequence INTEGER PRIMARY KEY AUTOINCREMENT, experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, event_id TEXT NOT NULL, source_sequence TEXT NOT NULL, event_type TEXT NOT NULL, event_hash TEXT NOT NULL, body_json TEXT NOT NULL CHECK(json_valid(body_json)), received_at TEXT NOT NULL, receipt_id TEXT NOT NULL, UNIQUE(experiment_id,run_id,event_id), UNIQUE(experiment_id,run_id,source_sequence), FOREIGN KEY(experiment_id,run_id) REFERENCES runs(experiment_id,run_id));
CREATE INDEX event_type_order ON events(experiment_id,run_id,event_type,receiver_sequence);
CREATE TABLE records (experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, kind TEXT NOT NULL, record_id TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>=0), event_id TEXT NOT NULL, PRIMARY KEY(experiment_id,run_id,kind,record_id,version), FOREIGN KEY(experiment_id,run_id,event_id) REFERENCES events(experiment_id,run_id,event_id));
CREATE TABLE record_links (experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, event_id TEXT NOT NULL, kind TEXT NOT NULL, record_id TEXT NOT NULL, version INTEGER NOT NULL, relation TEXT NOT NULL, PRIMARY KEY(experiment_id,run_id,event_id,kind,record_id,version,relation), FOREIGN KEY(experiment_id,run_id,event_id) REFERENCES events(experiment_id,run_id,event_id), FOREIGN KEY(experiment_id,run_id,kind,record_id,version) REFERENCES records(experiment_id,run_id,kind,record_id,version));
CREATE TABLE financial_journal (experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, sequence TEXT NOT NULL, source_operation TEXT NOT NULL, journal_hash TEXT NOT NULL, event_id TEXT NOT NULL, PRIMARY KEY(experiment_id,run_id,sequence), UNIQUE(experiment_id,run_id,source_operation), UNIQUE(experiment_id,run_id,journal_hash), FOREIGN KEY(experiment_id,run_id,event_id) REFERENCES events(experiment_id,run_id,event_id));
CREATE TABLE order_identities (experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, order_id TEXT NOT NULL, decision_id TEXT NOT NULL, decision_revision INTEGER NOT NULL, order_index INTEGER NOT NULL, PRIMARY KEY(experiment_id,run_id,order_id), UNIQUE(experiment_id,run_id,decision_id,decision_revision,order_index));
CREATE TABLE valuations (experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, valuation_id TEXT NOT NULL, sequence TEXT NOT NULL, PRIMARY KEY(experiment_id,run_id,valuation_id), UNIQUE(experiment_id,run_id,sequence), FOREIGN KEY(experiment_id,run_id) REFERENCES runs(experiment_id,run_id));
CREATE TABLE snapshots (experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, valuation_id TEXT NOT NULL, revision INTEGER NOT NULL, journal_sequence TEXT NOT NULL, event_id TEXT NOT NULL, PRIMARY KEY(experiment_id,run_id,valuation_id,revision), FOREIGN KEY(experiment_id,run_id,valuation_id) REFERENCES valuations(experiment_id,run_id,valuation_id), FOREIGN KEY(experiment_id,run_id,journal_sequence) REFERENCES financial_journal(experiment_id,run_id,sequence), FOREIGN KEY(experiment_id,run_id,event_id) REFERENCES events(experiment_id,run_id,event_id));
CREATE TABLE projections (experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, projection TEXT NOT NULL, identity TEXT NOT NULL, event_id TEXT NOT NULL, PRIMARY KEY(experiment_id,run_id,projection,identity), FOREIGN KEY(experiment_id,run_id,event_id) REFERENCES events(experiment_id,run_id,event_id));
CREATE TABLE discussion_ordinals (experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, discussion_id TEXT NOT NULL, ordinal TEXT NOT NULL, contribution_id TEXT NOT NULL, event_id TEXT NOT NULL, PRIMARY KEY(experiment_id,run_id,discussion_id,ordinal), UNIQUE(experiment_id,run_id,contribution_id), FOREIGN KEY(experiment_id,run_id,event_id) REFERENCES events(experiment_id,run_id,event_id));
CREATE TABLE content_objects (sha256 TEXT PRIMARY KEY, size_bytes INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE staged_content (experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, sha256 TEXT NOT NULL REFERENCES content_objects(sha256), content_type TEXT NOT NULL, touched_at INTEGER NOT NULL, PRIMARY KEY(experiment_id,run_id,sha256,content_type));
CREATE TABLE artifact_versions (experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, artifact_id TEXT NOT NULL, version INTEGER NOT NULL, sha256 TEXT NOT NULL, content_type TEXT NOT NULL, event_id TEXT NOT NULL, PRIMARY KEY(experiment_id,run_id,artifact_id,version), FOREIGN KEY(experiment_id,run_id,sha256,content_type) REFERENCES staged_content(experiment_id,run_id,sha256,content_type), FOREIGN KEY(experiment_id,run_id,event_id) REFERENCES events(experiment_id,run_id,event_id));
CREATE TABLE request_receipts (publisher_id TEXT NOT NULL REFERENCES publishers(publisher_id), experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, request_id TEXT NOT NULL, target TEXT NOT NULL, body_digest TEXT NOT NULL, response_json TEXT NOT NULL CHECK(json_valid(response_json)), PRIMARY KEY(publisher_id,experiment_id,run_id,request_id));
CREATE TABLE heartbeats (publisher_id TEXT PRIMARY KEY REFERENCES publishers(publisher_id), sent_at TEXT NOT NULL, received_at TEXT NOT NULL, body_json TEXT NOT NULL CHECK(json_valid(body_json)));
CREATE TABLE visibility_actions (id INTEGER PRIMARY KEY, experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, event_id TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN('withheld','withdrawn')), recorded_at TEXT NOT NULL, FOREIGN KEY(experiment_id,run_id,event_id) REFERENCES events(experiment_id,run_id,event_id));
CREATE INDEX visibility_target ON visibility_actions(experiment_id,run_id,event_id);
CREATE TABLE cursors (token TEXT PRIMARY KEY, binding TEXT NOT NULL, epoch TEXT NOT NULL, visibility_epoch INTEGER NOT NULL, upper_watermark INTEGER NOT NULL, after_sequence INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE INDEX cursor_expiry ON cursors(expires);
CREATE TRIGGER events_no_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'immutable event'); END;
CREATE TRIGGER events_no_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'immutable event'); END;
CREATE TRIGGER batches_no_update BEFORE UPDATE ON batches BEGIN SELECT RAISE(ABORT,'immutable batch'); END;
CREATE TRIGGER batches_no_delete BEFORE DELETE ON batches BEGIN SELECT RAISE(ABORT,'immutable batch'); END;
CREATE TRIGGER requests_no_update BEFORE UPDATE ON request_receipts BEGIN SELECT RAISE(ABORT,'immutable request'); END;
CREATE TABLE publication_approvals (experiment_id TEXT NOT NULL, run_id TEXT NOT NULL, configuration_hash TEXT NOT NULL, approved_at TEXT NOT NULL, PRIMARY KEY(experiment_id,run_id,configuration_hash));
